const isTruthy = (v) => ['true', '1', 'yes', 'y'].includes(String(v ?? '').trim().toLowerCase());
const isValidEmail = (email) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(email || '').trim());
const now = new Date();
const minDaysBetweenTouches = Number($env.MIN_DAYS_BETWEEN_TOUCHES || 7);
const rows = items.map((item) => item.json);
const dedupe = new Set();

const eligible = [];
for (const row of rows) {
  const email = String(row.email || '').trim().toLowerCase();
  const status = String(row.status || 'new').trim().toLowerCase();
  const unsubscribed = isTruthy(row.unsubscribed);
  const bounced = isTruthy(row.bounced);
  const replied = isTruthy(row.replied);

  if (!email || !isValidEmail(email)) continue;
  if (unsubscribed || bounced || replied) continue;
  if (!['new', 'retry'].includes(status)) continue;
  if (dedupe.has(email)) continue;

  const nextSendAt = row.next_send_at ? new Date(row.next_send_at) : null;
  if (nextSendAt && !Number.isNaN(nextSendAt.getTime()) && nextSendAt > now) continue;

  const lastContactedAt = row.last_contacted_at ? new Date(row.last_contacted_at) : null;
  if (lastContactedAt && !Number.isNaN(lastContactedAt.getTime())) {
    const diffDays = (now.getTime() - lastContactedAt.getTime()) / (1000 * 60 * 60 * 24);
    if (diffDays < minDaysBetweenTouches) continue;
  }

  dedupe.add(email);
  eligible.push({
    ...row,
    email,
    status,
    domain: String(row.domain || email.split('@')[1] || '').trim().toLowerCase()
  });
}

eligible.sort((a, b) => Number(b.priority_score || 0) - Number(a.priority_score || 0));
return eligible.map((row) => ({ json: row }));

const dailyLimit = Number($env.DAILY_OUTREACH_LIMIT || 20);
const selected = items.slice(0, dailyLimit);
return selected;

