const raw = String($json.body || $json.data || $json.response || '');
const withoutScript = raw.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ');
const text = withoutScript.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 5000);

return [{
  json: {
    ...lead,
    website_text: text || '',
    research_summary: text ? text.slice(0, 1200) : ''
  }
}];

