const lead = $item(0).$node['Build Research Context'].json;
const response = $json;
const text = response?.content?.[0]?.text || '{}';
let parsed;

try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {
    subject: `Quick question about ${lead.company || lead.domain || 'your business'}`,
    body: `Hi ${lead.first_name || ''},\n\nI work with Australian businesses to automate repetitive admin tasks and improve response times to new enquiries. If helpful, I can share a few practical ideas based on ${lead.company || 'your business'} and your current setup.\n\nWould a quick 15-minute chat next week be useful?`,
    pain_point: '',
    cta: 'Would a quick 15-minute chat next week be useful?'
  };
}

const unsubscribe = `${$env.UNSUBSCRIBE_BASE_URL || 'https://YOUR_DOMAIN/unsubscribe'}?email=${encodeURIComponent(lead.email)}`;
const signature = `\n\nBen\nRelayAI | Business Automation\nrelayai.com.au\nABN: 46 873 536 821\nUnsubscribe: ${unsubscribe}`;

const bodyText = String(parsed.body || '').trim();
const sanitizedBody = bodyText.replace(/unsubscrib(e|ing).*$/gim, '').trim();

return [{
  json: {
    ...lead,
    subject: String(parsed.subject || `Quick question about ${lead.company || lead.domain || 'your business'}`).slice(0, 120),
    body: `${sanitizedBody}${signature}`,
    outreach_status: 'draft_ready',
    generated_at: new Date().toISOString()
  }
}];

return [{
  json: {
    ...$json,
    outreach_status: 'draft_ready',
    draft_created_at: new Date().toISOString()
  }
}];
